import{z as B,x as i,o as A,c as p,q as l,j as s,D as t,d as a,s as r,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"规划域的分解","description":"","frontmatter":{"title":"规划域的分解","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pl-domain-decomposition.md","filePath":"llm/pl-domain-decomposition.md","lastUpdated":1791063341000}'),d={name:"llm/pl-domain-decomposition.md"};function m(h,E,D,f,C,F){const o=i("Mermaid");return A(),p("div",null,[E[2]||(E[2]=l('<h1 id="规划域的分解" tabindex="-1">规划域的分解 <a class="header-anchor" href="#规划域的分解" aria-label="Permalink to &quot;规划域的分解&quot;">​</a></h1><div class="epigraph"><p>分解不是把问题说小一点，而是造出一批各自可解、接口闭合的子问题；接口拆错，后面每一步都在精确地解一个错问题。</p><footer>—— 据 Zhou et al., Least-to-Most Prompting, 2022；Wang et al., Plan-and-Solve, ACL 2023；Besta et al., Graph of Thoughts, 2023 整理</footer></div><p><a href="/llm/pl-reflection-design">上一课</a>写的是在既有问题里修正路径：触发、内容与停止判据。但有些失败不在路径而在问题本身——多跳依赖太长、组合深度超出单链外推能力，错不是因为没想清楚，而是因为问题从来没有被拆到「一步可解」的粒度。缺口是分解：把规划域拆成子问题，让每次求解只面对一个可核对的局部。本课写分解的三种形态、接口约束与误差传播；<a href="/llm/least-to-most">Least-to-Most</a> 与 <a href="/llm/self-ask">Self-Ask</a> 的提示形态不重讲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/chain-of-thought">思维链</a>在组合外推上失效：训练分布里见过的步数内它步步行，超出后缺步、跳步、把未求出的中间量直接写进最终式。Plan-and-Solve 用「先写计划再求解」压缺步，但计划仍是同一条轨迹上的文本，没有独立求解与回填边界。分解走得更远：先产出子问题序列，再<strong>多次调用</strong>逐个求解，子答案回填进后续上下文。这引入了新的失败面——分解本身会错：子问题前置缺失（第 3 问依赖一个没人求过的量）、覆盖不全（子问题加起来不回答原问题）、粒度失衡（细到每次调用只做一次加法，粗到退化回单链）。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三种形态按结构从弱到强。<strong>序列分解</strong>（Least-to-Most）：子问题排成有序链，第 \\(i\\) 个子问题的条件里回填前 \\(i-1\\) 个子答案；适合依赖单向、深度可数的任务。<strong>递归分解</strong>：目标拆成子目标，子目标再拆，直到到达可直接求解的叶子；深度可变，适合层次分明的规划域（证明的引理、路线的区段）。<strong>图分解</strong>（<a href="/llm/graph-of-thoughts">Graph of Thoughts</a>）：子问题独立并行，部分解在宿主里聚合与精炼；适合分治后必须合流的任务。</p><p>三条约束跨形态通用。接口闭合：每个子问题的输入必须由前文或环境可满足，发现悬空引用应早失败，而不是让求解器编造。覆盖检查：子问题集合要能拼回原问题，这可以在分解产出时用一次核对调用检查。可验证：每个子问题应有局部判据——能规则核对的用规则，不能的至少核对类型与量纲。</p><p><span class="marginnote">「接口闭合」翻译成大白话：每个子问题要用的已知条件，必须已经躺在题目原文或前面子问题的答案里。如果第 3 问用到一个「没人算过的量」，这就是悬空引用——求解器多半会现编一个像模像样的数。早失败、重新拆，比让它在编造的数字上精确推理要便宜得多。</span></p><p><span class="marginnote">Zhou 等人在 SCAN 组合泛化拆分上报告：思维链只有约 16% 的准确率，least-to-most 达到 99.7%——分解的收益集中在「单链外推不动」的组合深度上；单链本来就会的题，分解只增加调用与出错机会。</span></p>',10)),(A(),s(n,null,{default:t(()=>[r(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%8E%9F%E9%97%AE%E9%A2%98%22%5D%20--%3E%20FORM%7B%22%E5%88%86%E8%A7%A3%E5%BD%A2%E6%80%81%22%7D%0A%20%20FORM%20--%3E%7C%E5%BA%8F%E5%88%97%7C%20SEQ%5B%22%E5%AD%90%E9%97%AE%E9%A2%98%E6%8E%92%E6%88%90%E6%9C%89%E5%BA%8F%E9%93%BE%EF%BC%8C%E9%80%90%E4%B8%AA%E6%B1%82%E8%A7%A3%E5%9B%9E%E5%A1%AB%22%5D%0A%20%20FORM%20--%3E%7C%E9%80%92%E5%BD%92%7C%20REC%5B%22%E7%9B%AE%E6%A0%87%E6%8B%86%E5%AD%90%E7%9B%AE%E6%A0%87%EF%BC%8C%E5%88%B0%E5%8F%B6%E5%AD%90%E5%8F%AF%E8%A7%A3%22%5D%0A%20%20FORM%20--%3E%7C%E5%9B%BE%7C%20GRAPH%5B%22%E5%AD%90%E9%97%AE%E9%A2%98%E7%8B%AC%E7%AB%8B%E6%B1%82%E8%A7%A3%EF%BC%8C%E5%AE%BF%E4%B8%BB%E8%81%9A%E5%90%88%22%5D%0A%20%20SEQ%20--%3E%20CHKS%5B%22%E6%8E%A5%E5%8F%A3%E9%97%AD%E5%90%88%20%2F%20%E8%A6%86%E7%9B%96%20%2F%20%E5%8F%AF%E9%AA%8C%E8%AF%81%22%5D%0A%20%20REC%20--%3E%20CHKS%0A%20%20GRAPH%20--%3E%20CHKS%0A%20%20CHKS%20--%3E%20SOLVE%5B%22%E9%80%90%E4%B8%AA%E6%B1%82%E8%A7%A3%EF%BC%8C%E5%AE%BF%E4%B8%BB%E9%92%89%E4%BD%8F%E5%AD%90%E7%AD%94%E6%A1%88%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("分解误差沿回填协议传播，且比单链更难改口：单链错一步可以"),e("a",{href:"/llm/self-verification-backtrack"},"回溯"),a("，分解错是结构错——第 1 问的答案错了，第 3 问在忠实求解一个错前提。所以宿主必须钉住每个子答案：子问题与子答案都写进后续上下文的是「钉住」，任由模型转述是「漂移」。成本上分解是多次调用加回填 token，收益来自重复使用的短求解；简单题上它是纯开销。与 "),e("a",{href:"/llm/tree-of-thoughts"},"ToT"),a(" 的分工：分解默认串行不分叉，把深度问题摊平；要在同一子问题上比选多个候选，才轮到上一课的树与分数。")],-1)),(A(),s(n,null,{default:t(()=>[r(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q1%5B%22%E5%AD%90%E9%97%AE%E9%A2%98%201%EF%BC%9A%E6%B1%82%E4%B8%AD%E9%97%B4%E9%87%8F%20a%22%5D%20--%3E%20A1%5B%22%E5%AD%90%E7%AD%94%E6%A1%88%20a%20%E5%87%BA%E9%94%99%22%5D%0A%20%20A1%20--%3E%20Q2%5B%22%E5%AD%90%E9%97%AE%E9%A2%98%202%20%E7%9A%84%E6%9D%A1%E4%BB%B6%E5%9B%9E%E5%A1%AB%20a%22%5D%0A%20%20A1%20--%3E%20Q3%5B%22%E5%AD%90%E9%97%AE%E9%A2%98%203%20%E7%9A%84%E6%9D%A1%E4%BB%B6%E5%9B%9E%E5%A1%AB%20a%22%5D%0A%20%20Q2%20--%3E%20F%5B%22%E5%9C%A8%E9%94%99%20a%20%E4%B8%8A%E7%B2%BE%E7%A1%AE%E6%B1%82%E8%A7%A3%22%5D%0A%20%20Q3%20--%3E%20F%0A%20%20F%20--%3E%20FIN%5B%22%E6%9C%80%E7%BB%88%E7%AD%94%E6%A1%88%EF%BC%9A%E7%BB%93%E6%9E%84%E6%80%A7%E5%9C%B0%E9%94%99%22%5D%0A%20%20PIN%5B%22%E5%AE%BF%E4%B8%BB%E9%92%89%E4%BD%8F%E5%AD%90%E7%AD%94%E6%A1%88%20%2B%20%E5%B1%80%E9%83%A8%E5%88%A4%E6%8D%AE%E6%A0%B8%E5%AF%B9%22%5D%20-.-%3E%7C%22%E5%8F%AF%E6%97%A9%E5%8F%91%E7%8E%B0%22%7C%20A1%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<p><span class="marginnote">「结构错 vs 路径错」的直觉类比：瓦工贴歪一块砖是路径错，撬掉重贴就行；图纸把承重墙画错了是结构错，后面每个房间都照错的图纸施工，而且每间都「施工得很精确」。分解把推理从贴砖升级成看图纸，所以它出错时也更贵——错在拆题这一步，后面每次调用都在放大它。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>分解适用于结构与依赖可显式表达的任务；开放域里模型会提出幻觉子目标，覆盖检查也只剩模型自评，收益上限随之封顶。分解产出的是子问题序列，不是可调度 DAG——要把节点换成工具调用、依赖边换成执行计划，是下一课工具规划的事。粒度没有免费午餐：切得太细，调用次数与回填误差同步放大；切得太粗，分解退化成一段更长的思维链，什么也没换来。</p><p><span class="marginnote">数字实例（示意）：一道 12 步的应用题，若拆成 40 个子问题，假设每次调用连回填要 600 token，光子问题就要约 2.4 万 token，还给了 40 个出错机会；反过来只拆成 2 个子问题，每个要单链跑 6 步——基本没享受分解的好处。好的粒度通常让每个子问题落在「一次调用、三五步内、有局部判据」的区间。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分解三形态：序列回填、递归到叶、图聚合；结构强度与适用域依次不同。</li><li>三条约束：接口闭合、覆盖、可验证；悬空引用应早失败。</li><li>误差沿回填传播且难改口；宿主必须钉住子答案，不许模型转述。</li><li>收益集中在组合外推；单链本来会的题，分解是纯开销。</li><li>分解产出不是可调度计划；换工具与执行器是下一课的题目。</li><li>出处：Zhou et al., <em>Least-to-Most Prompting</em>, 2022；Wang et al., <em>Plan-and-Solve</em>, ACL 2023；Besta et al., <em>Graph of Thoughts</em>, 2023。</li></ul>',6))])}const g=B(d,[["render",m]]);export{u as __pageData,g as default};
